package hikyubank;
import java.util.*;import java.time.*;import java.math.BigDecimal;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpSession;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;import org.springframework.http.*;import com.fasterxml.jackson.databind.*;
import hikyubank.application.service.*;import hikyubank.application.dto.BankingDtos.*;import hikyubank.application.dto.SecurityDtos.Registration;import hikyubank.application.dto.ExtensionDtos.TransferInput;import hikyubank.application.exception.BankException;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc class BankingBatchIntegrationTest {
 @Autowired BankingService banking;@Autowired PaymentAuthorizationService auth;@Autowired SecurityService security;@Autowired AccountService accounts;@Autowired TransferService transfers;@Autowired TransactionQueryService queries;@Autowired NotificationService notifications;@Autowired AlertService alerts;@Autowired AssistantService assistant;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired ObjectMapper mapper;
 UUID user,source,saving,credit;String username;String pin="0371",session="batch-session";
 @DynamicPropertySource static void db(DynamicPropertyRegistry p){BankApiIntegrationTest.databaseProperties(p);}
 @BeforeEach void setup(){username="batch_"+UUID.randomUUID().toString().substring(0,8);user=security.register(new Registration(username,"Batch","User","TestingPassword2026!",pin)).userId();source=accounts.list(user).stream().filter(a->a.type().equals("checking")).findFirst().orElseThrow().id();saving=accounts.list(user).stream().filter(a->a.type().equals("savings")).findFirst().orElseThrow().id();credit=UUID.randomUUID();jdbc.update("INSERT INTO hikyu.accounts(id,user_id,type,name,suffix,balance,status,credit_limit,minimum_due) VALUES(?,?,'credit','Demo Credit','4321',100,'active',1000,10)",credit,user);}
 OperationInput input(String type,UUID account,UUID target,UUID payee,String reference,String amount,UUID key){return new OperationInput(type,account,target,payee,reference,"purchase".equals(type)?"Demo merchant":null,"purchase".equals(type)?"Groceries":null,new BigDecimal(amount),"Batch test",key,pin,null,null,"sms");}
 OperationInput purchase(String amount,UUID key){return input("purchase",source,null,null,null,amount,key);}
 PaymentAuthorizationService.Challenge code(OperationInput p){banking.validate(user,p);return auth.issueBound(user,session,banking.fingerprint(p),p.method());}
 OperationReceipt submit(OperationInput p,PaymentAuthorizationService.Challenge c){return auth.execute(user,session,banking.fingerprint(p),c.challengeId(),c.demoCode(),()->banking.execute(user,p));}
 OperationReceipt submit(OperationInput p){return submit(p,code(p));}
 BigDecimal balance(UUID account){return accounts.get(user,account).balance();}
 @Test void debitPurchasePostsExpenseAndReceipt(){var r=submit(purchase("25.50",UUID.randomUUID()));assertEquals(new BigDecimal("974.50"),balance(source));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM hikyu.transactions WHERE operation_id=? AND kind='expense'",Integer.class,r.id()));assertEquals(1,notifications.list(user).size());assertEquals("purchase",banking.history(user).get(0).type());}
 @Test void creditPurchaseRaisesDebtAndRejectsLimit(){submit(input("purchase",credit,null,null,null,"50",UUID.randomUUID()));assertEquals(new BigDecimal("150.00"),balance(credit));var tooMuch=input("purchase",credit,null,null,null,"900",UUID.randomUUID());assertEquals("CREDIT_LIMIT_EXCEEDED",assertThrows(BankException.class,()->submit(tooMuch)).code());assertEquals(new BigDecimal("150.00"),balance(credit));}
 @Test void lockedCardBlocksNewPurchasesButAllowsRepayment(){banking.lockCard(user,credit,true);assertThrows(BankException.class,()->submit(input("purchase",credit,null,null,null,"1",UUID.randomUUID())));submit(input("repayment",source,credit,null,null,"25",UUID.randomUUID()));assertEquals(new BigDecimal("75.00"),balance(credit));assertEquals(new BigDecimal("0.00"),accounts.get(user,credit).minimumDue());assertTrue(banking.cards(user).stream().filter(c->c.accountId().equals(credit)).findFirst().orElseThrow().locked());banking.lockCard(user,credit,false);submit(input("purchase",credit,null,null,null,"1",UUID.randomUUID()));assertEquals(new BigDecimal("76.00"),balance(credit));}
 @Test void repaymentHasTwoLegsAndDoesNotCountAsSpending(){var r=submit(input("repayment",source,credit,null,null,"100",UUID.randomUUID()));assertEquals(new BigDecimal("900.00"),balance(source));assertEquals(new BigDecimal("0.00"),balance(credit));assertEquals(0,jdbc.queryForObject("SELECT sum(amount) FROM hikyu.transactions WHERE operation_id=?",BigDecimal.class,r.id()).signum());assertEquals(2,queries.search(user,null,null,null,null,null,"credit_payment","","","date_desc",0,10).total());assertEquals(0,queries.search(user,null,null,null,null,null,"income","","","date_desc",0,10).total());assertEquals(0,queries.search(user,null,null,null,null,null,"expense","","","date_desc",0,10).total());assertTrue(assistant.ask(user,"savings").reply().contains("Recorded income is $0.00 and spending is $0.00"));}
 @Test void overpaymentAndInsufficientFundsDoNotChangeBalances(){assertEquals("OVERPAYMENT",assertThrows(BankException.class,()->submit(input("repayment",source,credit,null,null,"101",UUID.randomUUID()))).code());assertEquals("INSUFFICIENT_FUNDS",assertThrows(BankException.class,()->submit(purchase("1001",UUID.randomUUID()))).code());assertEquals(new BigDecimal("1000.00"),balance(source));assertTrue(notifications.list(user).isEmpty());}
 @Test void billPayIsSimulatedAndPreservesHistoryAfterPayeeDelete(){var payee=banking.savePayee(user,new PayeeInput("biller","electric","Home power","demo-123"));var r=submit(input("bill",source,null,payee.id(),payee.reference(),"35",UUID.randomUUID()));assertEquals(new BigDecimal("965.00"),balance(source));assertEquals("Utilities",r.category());banking.deletePayee(user,payee.id());assertTrue(banking.payees(user).isEmpty());assertEquals(r.id(),banking.history(user).get(0).id());assertEquals(1,queries.search(user,null,null,null,null,null,"expense","","Utilities","date_desc",0,10).total());}
 @Test void payeeReferenceChangesInvalidatePendingConfirmation(){var payee=banking.savePayee(user,new PayeeInput("biller","internet","Internet","old-demo"));var p=input("bill",source,null,payee.id(),payee.reference(),"20",UUID.randomUUID());var c=code(p);banking.editPayee(user,payee.id(),new PayeeEdit("Internet","new-demo"));assertEquals("PAYEE_CHANGED",assertThrows(BankException.class,()->submit(p,c)).code());assertEquals(new BigDecimal("1000.00"),balance(source));}
 @Test void peerRecipientCrudValidatesKnownUserAndOwnership(){var recipient=banking.savePayee(user,new PayeeInput("peer","gospelhope.david","David",""));assertEquals("GD",banking.editPayee(user,recipient.id(),new PayeeEdit("GD","")).alias());var other=security.register(new Registration("other_"+username,"Other","User","TestingPassword2026!","9912")).userId();assertTrue(banking.payees(other).isEmpty());assertEquals(404,assertThrows(BankException.class,()->banking.editPayee(other,recipient.id(),new PayeeEdit("Hijack",""))).status());assertThrows(BankException.class,()->banking.savePayee(user,new PayeeInput("peer",username,"Self","")));banking.deletePayee(user,recipient.id());assertTrue(banking.payees(user).isEmpty());}
 @Test void invalidAmountForeignAccountAndIrrelevantFieldsAreRejected(){for(String amount:List.of("0","-1","1.001"))assertThrows(BankException.class,()->banking.execute(user,purchase(amount,UUID.randomUUID())));var other=security.register(new Registration("foreign_"+username,"Other","User","TestingPassword2026!","1919")).userId();var foreign=accounts.list(other).get(0).id();assertEquals(404,assertThrows(BankException.class,()->code(input("purchase",foreign,null,null,null,"1",UUID.randomUUID()))).status());assertThrows(BankException.class,()->code(input("purchase",saving,null,null,null,"1",UUID.randomUUID())));assertThrows(BankException.class,()->code(input("purchase",source,credit,null,null,"1",UUID.randomUUID())));}
 @Test void duplicateAndConflictingRequestsNeverDoubleDebit(){var key=UUID.randomUUID();var p=purchase("15",key);var c=code(p);var r=submit(p,c);banking.lockCard(user,source,true);assertEquals(r.id(),submit(p,c).id());assertEquals(new BigDecimal("985.00"),balance(source));assertEquals(1,notifications.list(user).size());var changed=purchase("16",key);assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BankException.class,()->submit(changed)).code());}
 @Test void parallelPurchasesWithSameKeyReturnOneReceipt()throws Exception{var p=purchase("20",UUID.randomUUID());var c=code(p);var pool=Executors.newFixedThreadPool(6);try{var tasks=new ArrayList<Callable<UUID>>();for(int i=0;i<12;i++)tasks.add(()->submit(p,c).id());var ids=new HashSet<UUID>();for(var f:pool.invokeAll(tasks))ids.add(f.get(15,TimeUnit.SECONDS));assertEquals(1,ids.size());assertEquals(new BigDecimal("980.00"),balance(source));}finally{pool.shutdownNow();}}
 @Test void parallelDistinctPurchasesCannotOverdraw()throws Exception{var a=purchase("700",UUID.randomUUID());var b=purchase("700",UUID.randomUUID());var ac=code(a);var bc=code(b);var pool=Executors.newFixedThreadPool(2);try{var tasks=List.<Callable<Boolean>>of(()->attempt(a,ac),()->attempt(b,bc));int ok=0;for(var f:pool.invokeAll(tasks))if(f.get(15,TimeUnit.SECONDS))ok++;assertEquals(1,ok);assertEquals(new BigDecimal("300.00"),balance(source));}finally{pool.shutdownNow();}}
 boolean attempt(OperationInput p,PaymentAuthorizationService.Challenge c){try{submit(p,c);return true;}catch(BankException e){assertEquals("INSUFFICIENT_FUNDS",e.code());return false;}}
 @Test void secondRepaymentLegFailureRollsBackAllFinancialState(){var p=input("repayment",source,credit,null,null,"25",UUID.randomUUID());var c=code(p);jdbc.execute("CREATE FUNCTION hikyu.test_batch_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.name='Credit repayment received' THEN RAISE EXCEPTION 'deliberate test'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER test_batch_failure BEFORE INSERT ON hikyu.transactions FOR EACH ROW EXECUTE FUNCTION hikyu.test_batch_failure()");try{assertThrows(Exception.class,()->submit(p,c));assertEquals(new BigDecimal("1000.00"),balance(source));assertEquals(new BigDecimal("100.00"),balance(credit));assertTrue(banking.history(user).isEmpty());assertTrue(notifications.list(user).isEmpty());assertFalse(jdbc.queryForObject("SELECT consumed FROM hikyu.payment_verifications WHERE id=?",Boolean.class,c.challengeId()));}finally{jdbc.execute("DROP TRIGGER test_batch_failure ON hikyu.transactions");jdbc.execute("DROP FUNCTION hikyu.test_batch_failure()");}submit(p,c);}
 @Test void enabledAndDisabledExpenseAlertsAreDeduplicated(){var rule=alerts.create(user,new hikyubank.application.dto.BankDtos.AlertRequest("low_balance",source,"Low balance","In-app",new BigDecimal("990"),null));var p=purchase("20",UUID.randomUUID());var c=code(p);submit(p,c);submit(p,c);assertEquals(2,notifications.list(user).size());alerts.toggle(user,rule.id(),false);submit(purchase("1",UUID.randomUUID()));assertEquals(3,notifications.list(user).size());}
 @Test void budgetsCountPurchasesExcludeRepaymentAndRespectMonth(){String month=YearMonth.now(ZoneOffset.UTC).toString();var b=banking.saveBudget(user,null,new BudgetInput(month,"Groceries",new BigDecimal("35")));submit(purchase("25",UUID.randomUUID()));submit(input("purchase",credit,null,null,null,"15",UUID.randomUUID()));submit(input("repayment",source,credit,null,null,"10",UUID.randomUUID()));var report=banking.budgets(user,month).get(0);assertEquals(new BigDecimal("40.00"),report.spent());assertEquals(new BigDecimal("-5.00"),report.remaining());assertTrue(report.exceeded());assertTrue(banking.budgets(user,YearMonth.now(ZoneOffset.UTC).minusMonths(1).toString()).isEmpty());banking.saveBudget(user,b.id(),new BudgetInput(month,"Groceries",new BigDecimal("50")));assertFalse(banking.budgets(user,month).get(0).exceeded());banking.deleteBudget(user,b.id());assertTrue(banking.budgets(user,month).isEmpty());assertThrows(BankException.class,()->banking.budgets(user,"bad-month"));}
 @Test void cardAndBudgetPermissionsAreIsolated(){var other=security.register(new Registration("iso_"+username,"Other","User","TestingPassword2026!","1919")).userId();assertEquals(404,assertThrows(BankException.class,()->banking.lockCard(other,source,true)).status());var b=banking.saveBudget(user,null,new BudgetInput(YearMonth.now(ZoneOffset.UTC).toString(),"Dining",BigDecimal.TEN));assertEquals(404,assertThrows(BankException.class,()->banking.saveBudget(other,b.id(),new BudgetInput(b.month(),"Dining",BigDecimal.ONE))).status());assertEquals(404,assertThrows(BankException.class,()->banking.deleteBudget(other,b.id())).status());}
 @Test void csvExportEscapesFormulaTextAndRejectsForeignAccount(){var p=new OperationInput("purchase",source,null,null,null,"=1+1","Groceries",BigDecimal.ONE,"=HYPERLINK(\"fake\")",UUID.randomUUID(),pin,null,null,"sms");submit(p);String csv=banking.statement(user,source,LocalDate.now(ZoneOffset.UTC),LocalDate.now(ZoneOffset.UTC));assertTrue(csv.contains("\"'=1+1\""));assertTrue(csv.contains("\"'=HYPERLINK(\"\"fake\"\")\""));assertTrue(csv.contains("Amount USD"));var other=security.register(new Registration("csv_"+username,"Other","User","TestingPassword2026!","1919")).userId();assertThrows(BankException.class,()->banking.statement(other,source,LocalDate.now(),LocalDate.now()));assertEquals(1,banking.statement(other,null,LocalDate.now(),LocalDate.now()).lines().count());assertThrows(BankException.class,()->banking.statement(user,null,LocalDate.now(),LocalDate.now().minusDays(1)));}
 @Test void financialOperationsRequireCodeAndPinAndBindThePayload(){var p=purchase("10",UUID.randomUUID());assertThrows(BankException.class,()->auth.execute(user,session,banking.fingerprint(p),null,null,()->banking.execute(user,p)));var c=code(p);var changed=purchase("11",p.idempotencyKey());assertThrows(BankException.class,()->submit(changed,c));var wrong=new OperationInput(p.type(),p.sourceAccountId(),null,null,null,p.merchant(),p.category(),p.amount(),p.note(),p.idempotencyKey(),"9999",null,null,"sms");assertThrows(BankException.class,()->submit(wrong,c));assertEquals(new BigDecimal("1000.00"),balance(source));}
 @Test void budgetUsesInclusiveMonthStartAndExcludesPreviousMonth(){var month=YearMonth.now(ZoneOffset.UTC);banking.saveBudget(user,null,new BudgetInput(month.toString(),"Groceries",new BigDecimal("5")));jdbc.update("INSERT INTO hikyu.transactions(id,account_id,name,category,posted_date,amount,icon,kind,note) VALUES(?,?,'Prior month','Groceries',?,-99,'X','expense','Boundary test')",UUID.randomUUID(),source,java.sql.Date.valueOf(month.atDay(1).minusDays(1)));submit(purchase("5",UUID.randomUUID()));var b=banking.budgets(user,month.toString()).get(0);assertEquals(new BigDecimal("5.00"),b.spent());assertEquals(new BigDecimal("0.00"),b.remaining());assertFalse(b.exceeded());}
 @Test void concurrentCardLockAndPurchaseHaveAConsistentOutcome()throws Exception{var p=purchase("10",UUID.randomUUID());var c=code(p);var pool=Executors.newFixedThreadPool(2);try{var latch=new CountDownLatch(1);var spend=pool.submit(()->{latch.await();try{submit(p,c);return true;}catch(BankException e){assertEquals("CARD_LOCKED",e.code());return false;}});var lock=pool.submit(()->{latch.await();banking.lockCard(user,source,true);return true;});latch.countDown();assertTrue(lock.get(15,TimeUnit.SECONDS));boolean spent=spend.get(15,TimeUnit.SECONDS);assertEquals(new BigDecimal(spent?"990.00":"1000.00"),balance(source));assertTrue(banking.cards(user).stream().filter(card->card.accountId().equals(source)).findFirst().orElseThrow().locked());}finally{pool.shutdownNow();}}

}
